messages.content:
Schema:
CREATE TABLE products (id INTEGER, name TEXT, price REAL, active INTEGER);
Question: List active product names costing less than 20, ordered by name.

Schema:
CREATE TABLE tickets (id INTEGER, status TEXT, priority TEXT);
Question: Count open tickets marked urgent.

Schema:
CREATE TABLE books (id INTEGER, title TEXT, author TEXT);
Question: Show each distinct author alphabetically.

Schema:
CREATE TABLE invoices (id INTEGER, customer_id INTEGER, amount REAL, paid_at TEXT);
Question: List unpaid invoice IDs and amounts, largest amount first, then ID ascending.

Schema:
CREATE TABLE visits (id INTEGER, page TEXT, visited_at TEXT);
Question: Count visits per page, most visited first, breaking ties by page.

Schema:
CREATE TABLE employees (id INTEGER, name TEXT, department TEXT, salary REAL);
Question: Find the average salary in each department. Order by department.

Schema:
CREATE TABLE orders (id INTEGER, customer_id INTEGER); CREATE TABLE customers (id INTEGER, name TEXT);
Question: Show order IDs with customer names, ordered by order ID.

Schema:
CREATE TABLE inventory (sku TEXT, available INTEGER, reorder_level INTEGER);
Question: Which SKUs have stock at or below their reorder level? Sort by SKU.

Schema:
CREATE TABLE sessions (id INTEGER, started_at TEXT);
Question: Count sessions starting in March 2026, using 1 April as the exclusive end.

Schema:
CREATE TABLE contacts (id INTEGER, email TEXT);
Question: Find email addresses used by more than one contact, excluding null addresses. Sort alphabetically.

Schema:
CREATE TABLE tasks (id INTEGER, title TEXT, due_date TEXT, completed INTEGER);
Question: List unfinished tasks due before 2026-05-01, earliest due first, then ID.

Schema:
CREATE TABLE articles (id INTEGER, title TEXT, published INTEGER);
Question: Show the titles of published articles containing "SQLite". Order by title.

Schema:
CREATE TABLE payments (id INTEGER, currency TEXT, amount REAL);
Question: Total payment amounts by currency, ordered by currency.

Schema:
CREATE TABLE events (id INTEGER, name TEXT, capacity INTEGER, booked INTEGER);
Question: List event names and remaining places for events that are not full. Sort by name.

Schema:
CREATE TABLE accounts (id INTEGER, created_at TEXT, closed_at TEXT);
Question: Count accounts that have not been closed.

Schema:
CREATE TABLE ratings (product_id INTEGER, score INTEGER);
Question: Show products with at least 5 ratings and an average score of at least 4. Order by product ID.

Schema:
CREATE TABLE authors (id INTEGER, name TEXT); CREATE TABLE posts (id INTEGER, author_id INTEGER);
Question: List authors with no posts, ordered by author ID.

Schema:
CREATE TABLE measurements (sensor_id INTEGER, temperature REAL);
Question: Show the minimum and maximum temperature for sensor 7.

Schema:
CREATE TABLE shipments (id INTEGER, status TEXT, shipped_at TEXT);
Question: Return the 3 most recently shipped shipments, breaking timestamp ties by ID descending.

Schema:
CREATE TABLE members (id INTEGER, display_name TEXT, email TEXT);
Question: Show IDs and display names, using the email when the display name is null. Order by ID.

Schema:
CREATE TABLE order_lines (order_id INTEGER, quantity INTEGER, unit_price REAL);
Question: Calculate the total for order 42. Return zero when it has no lines.

Schema:
CREATE TABLE logs (id INTEGER, severity TEXT);
Question: Count only warning and error log entries.

Schema:
CREATE TABLE rooms (id INTEGER, name TEXT, floor INTEGER, seats INTEGER);
Question: Find rooms on floor 2 with at least 8 seats. Sort by seats, then name.

Schema:
CREATE TABLE refunds (id INTEGER, order_id INTEGER, amount REAL);
Question: Show order IDs whose total refunds exceed 100. Sort by order ID.

Schema:
CREATE TABLE files (id INTEGER, name TEXT, bytes INTEGER, deleted INTEGER);
Question: Total bytes occupied by files that are not deleted; return zero for an empty set.

Schema:
CREATE TABLE subscriptions (id INTEGER, plan TEXT, status TEXT);
Question: Count active subscriptions for each plan, ordered by plan.

Schema:
CREATE TABLE students (id INTEGER, name TEXT); CREATE TABLE enrolments (student_id INTEGER, course_id INTEGER);
Question: List students enrolled in course 3, without duplicates. Sort by student ID.

Schema:
CREATE TABLE work_items (id INTEGER, owner_id INTEGER, state TEXT);
Question: Show owner IDs with at least two blocked items. Ignore unassigned items and sort by owner ID.

Schema:
CREATE TABLE exchanges (id INTEGER, currency TEXT, rate REAL, recorded_at TEXT);
Question: Show the newest EUR rate, breaking ties by ID descending.

Schema:
CREATE TABLE notes (id INTEGER, body TEXT);
Question: List IDs of notes whose body is null or an empty string. Order by ID.

Schema:
CREATE TABLE deliveries (id INTEGER, expected_date TEXT, delivered_date TEXT);
Question: Count completed deliveries that arrived after their expected date.

Schema:
CREATE TABLE assets (id INTEGER, label TEXT, category TEXT);
Question: Show asset labels outside the categories laptop and phone, excluding null categories. Sort by label.

Schema:
CREATE TABLE sales (id INTEGER, sold_at TEXT, amount REAL);
Question: Sum sales by calendar day using the first 10 characters of sold_at. Sort by day.

Schema:
CREATE TABLE recipes (id INTEGER, title TEXT, preparation_minutes INTEGER);
Question: Show the two fastest recipes, with title as the tie-breaker.

Schema:
CREATE TABLE teams (id INTEGER, name TEXT); CREATE TABLE memberships (team_id INTEGER, user_id INTEGER);
Question: List every team with its member count, including empty teams. Order by team ID.

Schema:
CREATE TABLE coupons (code TEXT, expires_at TEXT, uses_left INTEGER);
Question: Find codes with remaining uses and expiry on or after 2026-07-01. Sort by code.

Schema:
CREATE TABLE messages (id INTEGER, sender_id INTEGER, recipient_id INTEGER, is_read INTEGER);
Question: Count unread messages addressed to user 9.

Schema:
CREATE TABLE runs (id INTEGER, status TEXT, elapsed_seconds REAL);
Question: Find the average duration of successful runs only.

Schema:
CREATE TABLE tags (id INTEGER, name TEXT); CREATE TABLE document_tags (document_id INTEGER, tag_id INTEGER);
Question: List tag names attached to document 6, removing duplicates and sorting alphabetically.

Schema:
CREATE TABLE stock_moves (id INTEGER, sku TEXT, delta INTEGER);
Question: Calculate net stock changes by SKU and show only nonzero totals, ordered by SKU.
